// Valida la solicitud, cuenta los días laborables y comprueba saldo, solapes y coincidencias con el equipo.
const f = $('Formulario').first().json;
const filas = $input.all().map((i) => i.json).filter((r) => r.empleado);

const DIAS_ANUALES = 22;
const EMPLEADOS = {
  'Marta Soler': { email: 'kavanasystems.info+marta.soler@gmail.com', departamento: 'Producción' },
  'Iván Ruiz': { email: 'kavanasystems.info+ivan.ruiz@gmail.com', departamento: 'Producción' },
  'Laura Gómez': { email: 'kavanasystems.info+laura.gomez@gmail.com', departamento: 'Producción' },
  'Sergio Mata': { email: 'kavanasystems.info+sergio.mata@gmail.com', departamento: 'Logística' },
  'Nuria Ferrer': { email: 'kavanasystems.info+nuria.ferrer@gmail.com', departamento: 'Administración' },
  'Carmen Vidal': { email: 'kavanasystems.info+carmen.vidal@gmail.com', departamento: 'Administración' },
  'Hugo Ortiz': { email: 'kavanasystems.info+hugo.ortiz@gmail.com', departamento: 'Comercial' },
  'Pablo Cano': { email: 'kavanasystems.info+pablo.cano@gmail.com', departamento: 'Calidad' }
};
const TIPOS = ['Vacaciones', 'Asuntos propios', 'Permiso retribuido'];
// Festivos nacionales fijos y Viernes Santo de 2026 y 2027.
const FESTIVOS = ['01-01', '01-06', '05-01', '08-15', '10-12', '11-01', '12-06', '12-08', '12-25'];
const VIERNES_SANTO = ['2026-04-03', '2027-03-26'];

const fail = (error) => [{ json: { error } }];
const dia = (s) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(s || ''));
  if (!m) return null;
  const d = new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));
  return Number.isNaN(d.getTime()) ? null : d;
};
const iso = (d) => d.toISOString().slice(0, 10);
const DIA_MS = 24 * 3600 * 1000;

const emp = EMPLEADOS[f.empleado];
if (!emp) return fail('Empleado no reconocido.');
if (!TIPOS.includes(f.tipo)) return fail('Tipo de ausencia no válido.');
const desde = dia(f.desde);
const hasta = dia(f.hasta);
if (!desde || !hasta) return fail('Indica las dos fechas.');
if (hasta < desde) return fail('La fecha final no puede ser anterior a la inicial.');
const hoy = dia($now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd'));
if ((hoy - desde) / DIA_MS > 7) return fail('No se pueden pedir ausencias de hace más de una semana.');
if ((desde - hoy) / DIA_MS > 366) return fail('No se pueden pedir ausencias con más de un año de antelación.');
if ((hasta - desde) / DIA_MS > 30) return fail('Cada solicitud admite como máximo 31 días seguidos.');

const laborable = (d) => {
  const s = iso(d);
  const w = d.getUTCDay();
  return w !== 0 && w !== 6 && !FESTIVOS.includes(s.slice(5)) && !VIERNES_SANTO.includes(s);
};
let dias = 0;
for (let d = new Date(desde); d <= hasta; d = new Date(d.getTime() + DIA_MS)) if (laborable(d)) dias++;
if (!dias) return fail('Esas fechas son fin de semana o festivo: no suman días laborables.');

const solapa = (r) => String(r.desde) <= iso(hasta) && String(r.hasta) >= iso(desde);
const mias = filas.filter((r) => r.empleado === f.empleado);
if (mias.some(solapa)) return fail('Ya tienes una solicitud pendiente o aprobada que coincide con esas fechas.');
if (mias.filter((r) => r.estado === 'Pendiente').length >= 3) return fail('Ya tienes 3 solicitudes pendientes de respuesta.');
if (filas.filter((r) => r.estado === 'Pendiente').length >= 20) return fail('Ahora mismo hay demasiadas solicitudes pendientes en la demo. Prueba más tarde.');

const anio = String(desde.getUTCFullYear());
const reservados = mias
  .filter((r) => r.tipo === 'Vacaciones' && String(r.desde).startsWith(anio))
  .reduce((a, r) => a + Number(r.dias), 0);
const saldo = DIAS_ANUALES - reservados;
if (f.tipo === 'Vacaciones' && dias > saldo) {
  return fail(`Pides ${dias} días de vacaciones y te quedan ${saldo} en ${anio}.`);
}

const coincidencias = filas
  .filter((r) => r.empleado !== f.empleado && r.departamento === emp.departamento && solapa(r))
  .map((r) => `${r.empleado} (${r.desde} a ${r.hasta}, ${String(r.estado).toLowerCase()})`);

return [{
  json: {
    fecha_solicitud: $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd HH:mm'),
    empleado: f.empleado,
    email: emp.email,
    departamento: emp.departamento,
    tipo: f.tipo,
    desde: iso(desde),
    hasta: iso(hasta),
    dias,
    saldo_previo: saldo,
    estado: 'Pendiente',
    comentario: String(f.comentario || '').trim().slice(0, 300),
    conflictos: coincidencias.join('; '),
    decidido_en: '',
  },
}];

// Arma el correo para la responsable con los datos de la solicitud y las coincidencias del equipo.
const r = $('Guardar solicitud').first().json;
const lineas = [
  `${r.empleado} (${r.departamento}) pide ${r.tipo.toLowerCase()}.`,
  '',
  `Fechas: del ${r.desde} al ${r.hasta} (${r.dias} días laborables)`,
  `Vacaciones antes de esta solicitud: quedaban ${r.saldo_previo} de 22 días`,
];
if (r.comentario) lineas.push(`Comentario: ${r.comentario}`);
lineas.push('');
lineas.push(r.conflictos ? `⚠ Coincide con: ${r.conflictos}` : 'Sin coincidencias con su departamento.');
return [{ json: {
  asunto: `${r.conflictos ? '⚠ ' : ''}Solicitud de ${r.tipo.toLowerCase()} · ${r.empleado} · ${r.desde} a ${r.hasta}`,
  mensaje: lineas.join('\n'),
} }];

// Convierte la respuesta de la responsable en el estado final y el correo para el empleado.
const r = $('Guardar solicitud').first().json;
const a = $json.data && $json.data.approved;
const estado = a === true ? 'Aprobada' : a === false ? 'Rechazada' : 'Caducada';
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const saldo = estado === 'Aprobada' && r.tipo === 'Vacaciones' ? r.saldo_previo - r.dias : r.saldo_previo;
const frase = {
  Aprobada: `Tu solicitud de ${r.tipo.toLowerCase()} ha sido <b>aprobada</b>.`,
  Rechazada: `Tu solicitud de ${r.tipo.toLowerCase()} ha sido <b>rechazada</b>. Habla con tu responsable si necesitas más información.`,
  Caducada: `Tu solicitud de ${r.tipo.toLowerCase()} <b>no ha tenido respuesta</b> en 5 días y se ha cerrado. Puedes volver a enviarla.`,
}[estado];
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1d2430">
<p>Hola ${esc(r.empleado.split(' ')[0])},</p>
<p>${frase}</p>
<p>Del ${esc(r.desde)} al ${esc(r.hasta)} · ${esc(r.dias)} días laborables.<br>
Vacaciones que te quedan este año: <b>${esc(saldo)}</b> de 22.</p>
<p style="color:#5b6676">Mensaje automático de la demo de RRHH. Todos los datos son inventados.</p></div>`;
return [{ json: {
  estado,
  decidido_en: $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd HH:mm'),
  email: r.email,
  asunto: `Tu solicitud de ${r.tipo.toLowerCase()} (${r.desde} a ${r.hasta}): ${estado.toLowerCase()}`,
  html,
} }];
